-- Procedimentos odontológicos da planilha Individual.xlsx (especialidade + nome; sem preço).
-- Exclusivo de conta clínica (e profissionais da clínica). Solo/salão não listam estes itens
-- via get_procedures_for_profile (ver 20260909150000_hide_dental_procedures_non_clinic.sql).
-- category = ODONTOLOGIA (filtro do odontograma); specialty = especialidade clínica da planilha.

ALTER TABLE public.procedures
  ALTER COLUMN specialty TYPE text;

COMMENT ON COLUMN public.procedures.specialty IS
  'Especialidade: estetico | corporal | injetaveis | tecnologia | bem_estar | avaliacao | odontologico | outros | ou rótulo odontológico (Avaliação, Dentística, etc.)';

-- Desativa seed provisório antigo (slugs genéricos), se existir
UPDATE public.procedures
SET is_active = false
WHERE is_global = true
  AND created_by IS NULL
  AND slug IN (
    'odontologia-consulta',
    'odontologia-limpeza-profilaxia',
    'odontologia-restauracao',
    'odontologia-tratamento-canal',
    'odontologia-extracao',
    'odontologia-coroa',
    'odontologia-implante',
    'odontologia-aplicacao-fluor',
    'odontologia-clareamento',
    'odontologia-raspagem-periodontal',
    'odontologia-selante',
    'odontologia-faceta',
    'odontologia-protese',
    'odontologia-ortodontia',
    'odontologia-radiografia',
    'odontologia-cirurgia-periodontal',
    'odontologia-ulectomia',
    'odontologia-remocao-tartaro'
  );

